EmailSearch.input_mapping:
def input_mapping(sender, keyword, time_range):
    import datetime
    # Convert a human-friendly time_range string into a concrete date range.
    # For example, if time_range is 'past month', we convert it into start_date and end_date.
    if time_range == 'past month':
        end_date = datetime.date.today().strftime('%Y-%m-%d')
        start_date = (datetime.date.today() - datetime.timedelta(days=30)).strftime('%Y-%m-%d')
    else:
        # For other time_range values, we default to None; in a real scenario, more parsing logic might be needed
        start_date = None
        end_date = None
    return {
        'from': sender,
        'keywords': [keyword],
        'date_range': {'start_date': start_date, 'end_date': end_date}
    }

