GoogleCalendarEventSearch.output_mapping:
def output_mapping(result):
    # result is expected to have an 'event_blocks' field which is a list
    event_blocks = result.get('event_blocks', [])
    if not event_blocks:
        return {'availability': True, 'conflicting_events': ''}
    else:
        # Create a string representation of conflicting events
        conflicts = []
        for block in event_blocks:
            # Attempt to extract event details if available, otherwise default to 'busy'
            event_name = block.get('event_name', 'busy')
            start = block.get('start_time', 'unknown start')
            end = block.get('end_time', 'unknown end')
            conflicts.append(f"{event_name} from {start} to {end}")
        conflict_str = '; '.join(conflicts)
        return {'availability': False, 'conflicting_events': conflict_str}

