    # Expect date_range as a string in the format 'YYYY-MM-DD to YYYY-MM-DD'
    parts = date_range.split('to')
    if len(parts) == 2:
        start_date = parts[0].strip()
        end_date = parts[1].strip()
    else:
        start_date = date_range.strip()
        end_date = date_range.strip()
    # Map abstract sender to concrete 'from' and keyword to a list in 'keywords'
