EmailSearch.output_mapping:
def output_mapping(result):
    # 'result' is expected to be the concrete output with an 'emails' array
    emails = result.get('emails', [])
    if not emails:
        return {'email_details': ''}
    # Choose the most recent email based on the 'timestamp' field
    most_recent = max(emails, key=lambda e: e.get('timestamp', ''))
    # Form a string with details (subject, timestamp, sender, recipient); if content is not provided we omit it
    details = f"Subject: {most_recent.get('subject', '')}, Date: {most_recent.get('timestamp', '')}, From: {most_recent.get('from', '')}, To: {most_recent.get('to', '')}"
    return {'email_details': details}

