GoogleCalendarEventSearch.output_mapping:
def output_mapping(result):
    # Get the list of event blocks from the concrete tool result
    event_blocks = result.event_blocks
    # If no events found, the calendar owner is available
    if not event_blocks:
        is_available = True
        conflicting_events = ''
    else:
        is_available = False
        # Construct a string summary of conflicting events
        conflicting_events = ', '.join([f"{ev.get('event_name', 'busy')} from {ev.get('start_time')} to {ev.get('end_time')}" for ev in event_blocks])
    return {'is_available': is_available, 'conflicting_events': conflicting_events}

