EmailSearch.input_mapping:
def input_mapping(sender_email, keyword, time_range):
    import datetime, re
    # Map the sender_email directly to the concrete tool's 'from'.
    # Convert the keyword into a list as the concrete tool expects keywords as an array.
    # Convert time_range into a date_range object. For this example, if time_range is exactly 'past month',
    # compute the start and end dates. Otherwise, try to match a 'YYYY-MM-DD to YYYY-MM-DD' pattern, or default to None.
    if time_range == 'past month':
        end_date = datetime.date.today()
        start_date = end_date - datetime.timedelta(days=30)
        date_range = {'start_date': start_date.strftime('%Y-%m-%d'), 'end_date': end_date.strftime('%Y-%m-%d')}
    else:
        match = re.match(r'(\d{4}-\d{2}-\d{2})\s*to\s*(\d{4}-\d{2}-\d{2})', time_range)
        if match:
            date_range = {'start_date': match.group(1), 'end_date': match.group(2)}
        else:
            date_range = None
    return {'from': sender_email, 'keywords': [keyword], 'date_range': date_range}

