def output_mapping(result):
    # Retrieve the list of event blocks
    event_blocks = result.get('event_blocks', [])
    # If no events, the time slot is available
    availability = len(event_blocks) == 0
    # Prepare a conflicting events string if there are any event blocks
    if not availability:
        # Concatenate each event's start and end time; you could customize this further if needed
        conflicting_events = '; '.join([f"{e.get('start_time', '')}-{e.get('end_time', '')}" for e in event_blocks])
    else:
        conflicting_events = ""
    return {'availability': availability, 'conflicting_events': conflicting_events}

